      "mobileSvg": "<svg class=\"course-diagram-svg mnu108-post-diagram\" viewBox=\"0 0 360 772.1\" width=\"100%\" role=\"img\" aria-labelledby=\"MNU108-14-13-4-m-t MNU108-14-13-4-m-d\" xmlns=\"http://www.w3.org/2000/svg\"><title id=\"MNU108-14-13-4-m-t\">Channel richness: tinggi menuju rendah</title><desc id=\"MNU108-14-13-4-m-d\">Channel richness: tinggi menuju rendah. Face-to-face; Video chat/conference → telephone; Electronic messages → letters/memos; Reports/bulletins</desc><defs><marker id=\"MNU108-14-13-4-m-arrow\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path class=\"svg-title\" d=\"M0 0 L10 5 L0 10 Z\"/></marker></defs><rect class=\"svg-bg\" width=\"360\" height=\"772.1\" rx=\"12\"/><rect class=\"svg-card\" x=\"18\" y=\"20\" width=\"324\" height=\"104.15\" rx=\"10\" stroke-width=\"1.5\"/><text class=\"svg-title\" x=\"32\" y=\"44\" font-size=\"17\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Face-to-face</tspan></text><text class=\"svg-text\" x=\"32\" y=\"76.95\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Multiple cues, cepat two-way</tspan></text><text class=\"svg-text\" x=\"32\" y=\"98.55000000000001\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">feedback, personal focus</tspan></text><path class=\"svg-title\" style=\"fill:none!important\" stroke=\"currentColor\" stroke-width=\"2\"  marker-end=\"url(#MNU108-14-13-4-m-arrow)\" d=\"M180 127.15 L180 154.15\"/><rect class=\"svg-card\" x=\"18\" y=\"158.15\" width=\"324\" height=\"127.10000000000001\" rx=\"10\" stroke-width=\"1.5\"/><text class=\"svg-title\" x=\"32\" y=\"182.15\" font-size=\"17\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Video chat/conference →</tspan><tspan x=\"32\" dy=\"22.950000000000003\">telephone</tspan></text><text class=\"svg-text\" x=\"32\" y=\"238.05\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Kurangi sebagian cues;</tspan></text><text class=\"svg-text\" x=\"32\" y=\"259.65000000000003\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">pertahankan percakapan</tspan></text><path class=\"svg-title\" style=\"fill:none!important\" stroke=\"currentColor\" stroke-width=\"2\"  marker-end=\"url(#MNU108-14-13-4-m-arrow)\" d=\"M180 288.25 L180 315.25\"/><rect class=\"svg-card\" x=\"18\" y=\"319.25\" width=\"324\" height=\"127.10000000000001\" rx=\"10\" stroke-width=\"1.5\"/><text class=\"svg-title\" x=\"32\" y=\"343.25\" font-size=\"17\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Electronic messages →</tspan><tspan x=\"32\" dy=\"22.950000000000003\">letters/memos</tspan></text><text class=\"svg-text\" x=\"32\" y=\"399.15\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Lebih mudah</tspan></text><text class=\"svg-text\" x=\"32\" y=\"420.75\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">didokumentasikan/disebarkan</tspan></text><path class=\"svg-title\" style=\"fill:none!important\" stroke=\"currentColor\" stroke-width=\"2\"  marker-end=\"url(#MNU108-14-13-4-m-arrow)\" d=\"M180 449.35 L180 476.35\"/><rect class=\"svg-card\" x=\"18\" y=\"480.35\" width=\"324\" height=\"125.75000000000001\" rx=\"10\" stroke-width=\"1.5\"/><text class=\"svg-title\" x=\"32\" y=\"504.35\" font-size=\"17\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Reports/bulletins</tspan></text><text class=\"svg-text\" x=\"32\" y=\"537.3000000000001\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Cocok untuk pesan rutin jelas</tspan></text><text class=\"svg-text\" x=\"32\" y=\"558.9000000000001\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">Feedback lebih lambat dan</tspan></text><text class=\"svg-text\" x=\"32\" y=\"580.5000000000001\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"32\" dy=\"0\">impersonal</tspan></text><text class=\"svg-text\" x=\"18\" y=\"640.1\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"18\" dy=\"0\">Richness berbeda dari panjang</tspan><tspan x=\"18\" dy=\"21.6\">pesan atau kecepatan mengirim.</tspan><tspan x=\"18\" dy=\"21.6\">Pilih channel berdasarkan</tspan><tspan x=\"18\" dy=\"21.6\">ambiguitas, emosi, kebutuhan</tspan><tspan x=\"18\" dy=\"21.6\">record dan audience.</tspan></text></svg>",
